// Procedurally synthesised sound effects + a small background-music loop.
// 100% generated by code -> no licensing issues.   node scripts/make-sfx.mjs
import {mkdirSync, writeFileSync} from 'node:fs';

const SR = 44100;

const writeWav = (path, channels) => {
  const n = channels[0].length;
  const ch = channels.length;
  const buf = Buffer.alloc(44 + n * ch * 2);
  buf.write('RIFF', 0);
  buf.writeUInt32LE(36 + n * ch * 2, 4);
  buf.write('WAVEfmt ', 8);
  buf.writeUInt32LE(16, 16);
  buf.writeUInt16LE(1, 20);
  buf.writeUInt16LE(ch, 22);
  buf.writeUInt32LE(SR, 24);
  buf.writeUInt32LE(SR * ch * 2, 28);
  buf.writeUInt16LE(ch * 2, 32);
  buf.writeUInt16LE(16, 34);
  buf.write('data', 36);
  buf.writeUInt32LE(n * ch * 2, 40);
  for (let i = 0; i < n; i++)
    for (let c = 0; c < ch; c++) {
      const v = Math.max(-1, Math.min(1, channels[c][i]));
      buf.writeInt16LE(Math.round(v * 32767), 44 + (i * ch + c) * 2);
    }
  writeFileSync(path, buf);
};

const normalize = (x, peak) => {
  let m = 0;
  for (const v of x) m = Math.max(m, Math.abs(v));
  return x.map((v) => (v / (m || 1)) * peak);
};

// deterministic noise
let seed = 1234567;
const rnd = () => {
  seed = (seed * 1664525 + 1013904223) >>> 0;
  return seed / 4294967296;
};
const noise = () => rnd() * 2 - 1;

const bandpass = () => {
  let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
  return (x, fc, q) => {
    const w0 = (2 * Math.PI * fc) / SR;
    const alpha = Math.sin(w0) / (2 * q);
    const a0 = 1 + alpha;
    const y = (alpha * x - alpha * x2 + 2 * Math.cos(w0) * y1 - (1 - alpha) * y2) / a0;
    x2 = x1; x1 = x; y2 = y1; y1 = y;
    return y;
  };
};

const pop = () => {
  const n = Math.floor(0.18 * SR);
  let ph = 0;
  return normalize(
    Array.from({length: n}, (_, i) => {
      const t = i / SR;
      const f = 260 + 950 * Math.exp(-t * 38);
      ph += (2 * Math.PI * f) / SR;
      const env = Math.exp(-t * 26) * (1 - Math.exp(-t * 3000));
      return Math.sin(ph) * env + (t < 0.004 ? noise() * 0.3 * (1 - t / 0.004) : 0);
    }),
    0.8,
  );
};

const whoosh = () => {
  const d = 0.55;
  const n = Math.floor(d * SR);
  const bp = bandpass();
  return normalize(
    Array.from({length: n}, (_, i) => {
      const t = i / SR;
      const p = t / d;
      const fc = 350 + 2600 * Math.sin(Math.PI * p) ** 2;
      return bp(noise(), fc, 1.1) * Math.sin(Math.PI * p) ** 1.6;
    }),
    0.55,
  );
};

const bell = (f0, t) =>
  [
    [1, 1, 3.2],
    [2.76, 0.42, 6.5],
    [5.4, 0.2, 11],
    [8.93, 0.1, 16],
  ].reduce((s, [r, a, k]) => s + a * Math.sin(2 * Math.PI * f0 * r * t) * Math.exp(-k * t), 0) * (1 - Math.exp(-t * 2500));

const ding = () => {
  const n = Math.floor(1.5 * SR);
  return normalize(
    Array.from({length: n}, (_, i) => {
      const t = i / SR;
      const t2 = t - 0.085;
      return bell(1318.5, t) + (t2 > 0 ? 0.9 * bell(1975.5, t2) : 0);
    }),
    0.6,
  );
};

const boing = () => {
  const n = Math.floor(0.6 * SR);
  let ph = 0;
  return normalize(
    Array.from({length: n}, (_, i) => {
      const t = i / SR;
      const f = 170 * (1 + 0.55 * Math.exp(-5 * t) * Math.sin(2 * Math.PI * 9 * t)) + 60 * t;
      ph += (2 * Math.PI * f) / SR;
      const w = Math.sin(ph) + Math.sin(3 * ph) / 9 + Math.sin(5 * ph) / 25;
      return w * Math.exp(-4.2 * t) * (1 - Math.exp(-t * 800));
    }),
    0.6,
  );
};

const click = () => {
  const n = Math.floor(0.05 * SR);
  return normalize(
    Array.from({length: n}, (_, i) => {
      const t = i / SR;
      return (noise() * 0.5 + Math.sin(2 * Math.PI * 2200 * t)) * Math.exp(-t * 140);
    }),
    0.6,
  );
};

// ---------------- music: cheerful plucked loop (Karplus-Strong) ----------------
const music = () => {
  const bpm = 104;
  const beat = 60 / bpm;
  const bars = 8;
  const loopLen = Math.floor(bars * 4 * beat * SR);
  const total = loopLen + 3 * SR;
  const L = new Float32Array(total);
  const R = new Float32Array(total);
  const midi = (m) => 440 * 2 ** ((m - 69) / 12);
  const pluck = (startSec, m, amp, pan) => {
    const f = midi(m);
    const N = Math.max(2, Math.round(SR / f));
    const buf = Float32Array.from({length: N}, () => noise());
    for (let k = 0; k < 2; k++) for (let i = 0; i < N; i++) buf[i] = 0.5 * (buf[i] + buf[(i + 1) % N]);
    const s0 = Math.floor(startSec * SR);
    const len = Math.floor(1.6 * SR);
    let idx = 0;
    for (let i = 0; i < len && s0 + i < total; i++) {
      const y = buf[idx];
      const nxt = (idx + 1) % N;
      buf[idx] = 0.4985 * (buf[idx] + buf[nxt]);
      idx = nxt;
      const v = y * amp;
      L[s0 + i] += v * (1 - pan);
      R[s0 + i] += v * (1 + pan);
    }
  };
  const bass = (startSec, m, dur) => {
    const f = midi(m);
    const s0 = Math.floor(startSec * SR);
    const len = Math.floor(dur * SR);
    for (let i = 0; i < len && s0 + i < total; i++) {
      const t = i / SR;
      const v = Math.tanh(1.6 * Math.sin(2 * Math.PI * f * t)) * Math.exp(-3.2 * t) * (1 - Math.exp(-t * 400)) * 0.32;
      L[s0 + i] += v;
      R[s0 + i] += v;
    }
  };
  const shaker = (startSec, amp) => {
    const s0 = Math.floor(startSec * SR);
    const bp = bandpass();
    for (let i = 0; i < 0.06 * SR && s0 + i < total; i++) {
      const t = i / SR;
      const v = bp(noise(), 7000, 0.8) * Math.exp(-t * 70) * amp;
      L[s0 + i] += v * 0.8;
      R[s0 + i] += v;
    }
  };
  const kick = (startSec) => {
    const s0 = Math.floor(startSec * SR);
    let ph = 0;
    for (let i = 0; i < 0.25 * SR && s0 + i < total; i++) {
      const t = i / SR;
      ph += (2 * Math.PI * (48 + 90 * Math.exp(-t * 30))) / SR;
      const v = Math.sin(ph) * Math.exp(-t * 14) * 0.35;
      L[s0 + i] += v;
      R[s0 + i] += v;
    }
  };
  // C  G  Am  F  |  C  G  F  G   (MIDI roots in octave 4 -> 60 = C4)
  const chords = [
    [60, 64, 67], [55, 59, 62], [57, 60, 64], [53, 57, 60],
    [60, 64, 67], [55, 59, 62], [53, 57, 60], [55, 59, 62],
  ];
  const pattern = [0, 1, 2, 3, 2, 1, 3, 2]; // index into [root, 3rd, 5th, octave]
  chords.forEach((c, bar) => {
    const notes = [c[0] + 12, c[1] + 12, c[2] + 12, c[0] + 24];
    for (let e = 0; e < 8; e++) {
      const t = (bar * 4 + e * 0.5) * beat;
      pluck(t, notes[pattern[e]], e % 2 === 0 ? 0.5 : 0.36, e % 2 === 0 ? -0.3 : 0.3);
    }
    bass(bar * 4 * beat, c[0] - 24, 1.6 * beat);
    bass((bar * 4 + 2) * beat, c[0] - 24, 1.6 * beat);
    bass((bar * 4 + 3.5) * beat, c[2] - 24, 0.5 * beat);
    kick(bar * 4 * beat);
    kick((bar * 4 + 2) * beat);
    for (let b = 0; b < 4; b++) shaker((bar * 4 + b + 0.5) * beat, 0.25);
  });
  // wrap the tail onto the start for a seamless loop
  for (let i = loopLen; i < total; i++) {
    L[i - loopLen] += L[i];
    R[i - loopLen] += R[i];
  }
  const outL = Array.from(L.subarray(0, loopLen));
  const outR = Array.from(R.subarray(0, loopLen));
  let m = 0;
  for (let i = 0; i < loopLen; i++) m = Math.max(m, Math.abs(outL[i]), Math.abs(outR[i]));
  return [outL.map((v) => (v / m) * 0.85), outR.map((v) => (v / m) * 0.85)];
};

mkdirSync('public/sfx', {recursive: true});
mkdirSync('public/music', {recursive: true});
writeWav('public/sfx/pop.wav', [pop()]);
writeWav('public/sfx/whoosh.wav', [whoosh()]);
writeWav('public/sfx/ding.wav', [ding()]);
writeWav('public/sfx/boing.wav', [boing()]);
writeWav('public/sfx/click.wav', [click()]);
writeWav('public/music/leesho-loop.wav', music());
console.log('sfx + music written to public/sfx and public/music');
